import { test, expect } from '@playwright/test';

test.describe('Empty State - No Notifications', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display empty state when no notifications exist', async ({ page }) => {
    // Verify the notifications list is empty
    const notificationsList = page.getByRole('list', { name: /notifications/i });
    await expect(notificationsList).toBeVisible();

    // Verify the empty state message is displayed
    const emptyStateMessage = page.getByText(/no notifications/i);
    await expect(emptyStateMessage).toBeVisible();

    // Verify the empty state illustration is visible
    const emptyStateIllustration = page.getByRole('img', { name: /empty state/i });
    await expect(emptyStateIllustration).toBeVisible();

    // Verify the empty state action button is visible
    const actionButton = page.getByRole('button', { name: /view all/i });
    await expect(actionButton).toBeVisible();

    // Verify the notification count badge is not present
    const notificationCountBadge = page.locator('[data-testid="notification-count-badge"]');
    await expect(notificationCountBadge).not.toBeVisible();
  });

  test('should handle empty state when user has viewed all notifications', async ({ page }) => {
    // Intercept API call to simulate no notifications
    await page.route('**/api/notifications', route => {
      route.abort();
    });

    // Navigate to notifications page
    await page.goto('/notifications');

    // Verify empty state message is displayed
    const emptyStateMessage = page.getByText(/no notifications/i);
    await expect(emptyStateMessage).toBeVisible();

    // Verify empty state illustration is visible
    const emptyStateIllustration = page.getByRole('img', { name: /empty state/i });
    await expect(emptyStateIllustration).toBeVisible();

    // Verify the user can still access the settings
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await expect(settingsButton).toBeVisible();

    // Verify the user can navigate back
    const backButton = page.getByRole('button', { name: /back/i });
    await expect(backButton).toBeVisible();
  });
});
